import{_ as t,o as s,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-6-remove-agency/report3_spec.md","filePath":"feature/agency-workspace/3-4-6-remove-agency/report3_spec.md"}'),a={name:"feature/agency-workspace/3-4-6-remove-agency/report3_spec.md"};function r(i,e,l,c,h,g){return s(),o("div",null,[...e[0]||(e[0]=[n("<p><strong>3.4.6 Remove Agency</strong></p><p><strong>Function Trigger</strong></p><p>The Owner of an Agency selects Remove in the Agency settings and confirms the removal dialog; or later selects Restore on an Agency removed within the last 30 days.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner.</li><li><strong>Purpose</strong>: Let the Owner take an Agency out of use without losing it, so it can be restored within 30 days.</li><li><strong>Interface</strong>: Remove action in Agency settings, behind a two-step confirmation dialog that asks the Owner to type the Agency name and states the consequences, including that the Workspaces of the Agency are affected too. Restore is available on removed Agencies within the 30-day window. On the FE, a danger-zone section groups the Remove and Restore actions.</li><li><strong>Data Processing</strong>: The system loads the Agency, confirms the caller is its Owner, marks the Agency soft-deleted with a removal timestamp, and marks every Workspace of that Agency the same way with the same timestamp. Restoring marks the Agency active again, clears the removal timestamp, and does the same for the Workspaces removed in that same batch — Workspaces already removed on their own keep their removed state.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Remove Agency dialog:</p><ul><li>A two-step confirmation: the Owner types the Agency name to confirm.</li><li>The dialog lists the consequences, notably that the Workspaces of the Agency are removed along with it.</li><li>A danger-zone section in the Agency settings groups the Remove action and, for a removed Agency, the Restore action, available for 30 days after removal.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId) and a signed-in session as its Owner.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the status and removal timestamp of the Agency (ACTIVE / SOFT_DELETED) and the status and removal timestamp of every Workspace belonging to the Agency.</li><li><strong>Output</strong>: removal leaves no profile to show. Restore returns the Agency profile with status ACTIVE.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-26 (analogous)</strong>: delete Agency is Owner-only, mirroring the rule that delete Workspace is OWNER-only. Anybody else is refused with 403 NOT_AGENCY_OWNER.</li><li>Removal is soft: the Agency is marked SOFT_DELETED and stamped with the removal time. Nothing is erased, and the Agency can be restored.</li><li>Removal cascades to the Workspaces of the Agency: each is marked SOFT_DELETED with the same removal time as the Agency.</li><li>Restore is allowed only on an Agency currently SOFT_DELETED; otherwise 400 AGENCY_NOT_DELETED.</li><li>Restore is allowed only within 30 days of the removal timestamp; beyond that, 410 RESTORE_WINDOW_EXPIRED.</li><li>Restore marks the Agency ACTIVE with the removal timestamp cleared, and does the same for the Workspaces whose removal timestamp matches the removal batch exactly. A Workspace already removed on its own beforehand keeps its removed state.</li><li>When the 30-day window passes without a restore, the Agency may eventually be erased for good by a periodic clean-up, designed separately and not part of this feature today.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Restore called on an Agency that was never removed → 400 AGENCY_NOT_DELETED.</li><li>Restore attempted more than 30 days after removal → 410 RESTORE_WINDOW_EXPIRED.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The Owner selects Remove in the Agency settings danger zone.</li><li>The confirmation dialog states the consequences and asks the Owner to type the Agency name.</li><li>The Owner confirms.</li><li>The system loads the Agency and confirms the caller is its Owner.</li><li>The system marks the Agency SOFT_DELETED with the current time.</li><li>The system marks every Workspace of the Agency SOFT_DELETED with the same removal time; toast <strong>MSG93</strong>.</li><li>The client shows a confirmation and takes the user back to the Agency list.</li><li>Within 30 days, the Owner selects Restore in the danger zone.</li><li>The system confirms the caller is the Owner, that the Agency is SOFT_DELETED, and that the removal happened less than 30 days ago.</li><li>The system marks the Agency ACTIVE with the removal timestamp cleared, and does the same for the Workspaces removed in that same batch.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Agency Owner → 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; nothing changes. 4.b2: The caller returns to the Agency list.</li><li>9.a1: Restore called on an Agency never removed → 400 AGENCY_NOT_DELETED, toast <strong>MSG38</strong> (closest fit). 9.a2: The Owner reloads the Agency list, which shows it as already active.</li><li>9.b1: Restore attempted after the 30-day window → 410 RESTORE_WINDOW_EXPIRED, toast <strong>MSG38</strong> (closest fit). 9.b2: The Owner accepts the Agency stays removed, or creates a new one.</li><li>10.a1: The Owner restores within 30 days after a mistaken removal → Workspaces removed in that same batch become ACTIVE again; no error. 10.a2: The Owner continues working in the restored Agency and its Workspaces.</li><li>10.b1: A Workspace had already been removed on its own beforehand → it is not brought back when the Agency is restored, since its removal timestamp differs from the removal batch; no error. 10.b2: The Owner restores that Workspace separately if still within its own window.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>After removal: the Agency and its Workspaces carry the SOFT_DELETED status and the same removal timestamp. Nothing is erased.</li><li>After a restore within the window: the Agency is ACTIVE with no removal timestamp, and Workspaces from the same removal batch are ACTIVE again, while Workspaces removed on their own stay removed.</li></ul>",14)])])}const p=t(a,[["render",r]]);export{d as __pageData,p as default};
